package main

import "core:fmt"

main :: proc() {
	for i in 1 ..= 15 {
		switch {
		case i % 15 == 0: fmt.println("FizzBuzz")
		case i % 3 == 0:  fmt.println("Fizz")
		case i % 5 == 0:  fmt.println("Buzz")
		case:             fmt.println(i)
		}
	}
}

higher-order.code:
package main

import "core:fmt"
import "core:slice"

main :: proc() {
	nums: [10]int
	for &n, i in nums do n = i + 1

	// Procedure literals cannot capture variables: Odin has no closures.
	// filter and mapper allocate their results, here from the scratch arena.
	evens := slice.filter(nums[:], proc(n: int) -> bool { return n % 2 == 0 }, context.temp_allocator)
	squares := slice.mapper(evens, proc(n: int) -> int { return n * n }, context.temp_allocator)
	defer free_all(context.temp_allocator)

	for s, i in squares {
		if i > 0 do fmt.print(" ")
		fmt.print(s)
	}
	fmt.println()
}

shapes.code:
package main

import "core:fmt"
import "core:reflect"

Rectangle :: struct { width, height: int }
Triangle  :: struct { base, height: int }

// A tagged union: the hidden tag records which variant is stored.
Shape :: union { Rectangle, Triangle }

area :: proc(s: Shape) -> int {
	switch v in s { // type switch: in each case `v` has that variant's type
	case Rectangle: return v.width * v.height
	case Triangle:  return v.base * v.height / 2
	}
	return 0 // only for a nil Shape
}

main :: proc() {
	shapes := []Shape{Rectangle{3, 4}, Triangle{10, 3}}
	for s in shapes {
		// Run-time type info: the variant's typeid prints as its name.
		fmt.printfln("%v: %d", reflect.union_variant_typeid(s), area(s))
	}
}
